import subprocess, sys
def run(src, args=None):
    a = ["/workspace/executable", "-"]
    if args: a = ["/workspace/executable"] + args + ["-"]
    p = subprocess.run(a, input=src.encode(), capture_output=True)
    return p.returncode, p.stdout.decode('utf-8','replace'), p.stderr.decode('utf-8','replace')
def show(src, args=None):
    c,o,e = run(src,args)
    print("IN  : " + repr(src))
    if o: print("OUT : " + repr(o))
    if e: print("ERR :\n" + e)
    print("EXIT: %d" % c)
    print("-"*60)
if __name__ == "__main__":
    for line in sys.stdin.read().split("\0"):
        if line.strip()=="" : continue
        show(line)
